function boundsOf(surface: ScatterSurface | null): Box {
  const p = surface?.positions
  if (!p || p.length === 0) return { min: [-1, -1, -1], size: [2, 2, 2] }
  const min: [number, number, number] = [Infinity, Infinity, Infinity]
  const max: [number, number, number] = [-Infinity, -Infinity, -Infinity]
  for (let i = 0; i < p.length; i += 3) {
    for (let a = 0; a < 3; a++) {
      if (p[i + a] < min[a]) min[a] = p[i + a]
      if (p[i + a] > max[a]) max[a] = p[i + a]
    }
  }
  return { min, size: [max[0] - min[0], max[1] - min[1], max[2] - min[2]] }
}

/** eixos da caixa do maior para o menor; no empate, X, Z e Y (o chão vem primeiro) */
const axesOf = (box: Box) => [0, 2, 1].sort((a, b) => box.size[b] - box.size[a])

const triangleCount = (s: ScatterSurface) => (s.index ? s.index.length : s.positions.length / 3) / 3

/** vértice \`corner\` (0 a 2) do triângulo \`tri\` */
const vertexOf = (s: ScatterSurface, tri: number, corner: number) => (s.index ? s.index[tri * 3 + corner] : tri * 3 + corner)

/** área acumulada por triângulo: a soma dá o peso de cada um */
function cumulativeArea(s: ScatterSurface): Float64Array {
  const p = s.positions
  const out = new Float64Array(triangleCount(s))
  let sum = 0
  for (let t = 0; t < out.length; t++) {
    const a = vertexOf(s, t, 0) * 3
    const b = vertexOf(s, t, 1) * 3
    const c = vertexOf(s, t, 2) * 3
    const ux = p[b] - p[a]
    const uy = p[b + 1] - p[a + 1]
    const uz = p[b + 2] - p[a + 2]
    const vx = p[c] - p[a]
    const vy = p[c + 1] - p[a + 1]
    const vz = p[c + 2] - p[a + 2]
    const cx = uy * vz - uz * vy
    const cy = uz * vx - ux * vz
    const cz = ux * vy - uy * vx
    sum += Math.sqrt(cx * cx + cy * cy + cz * cz) / 2
    out[t] = sum
  }
  return out
}

/** ponto ponderado pela área: \`pick\` escolhe o triângulo, \`r1\` e \`r2\` caem nele sem concentrar num canto */
function sampleSurface(s: ScatterSurface, areas: Float64Array, pick: number, r1: number, r2: number, out: Candidate) {
  const target = pick * areas[areas.length - 1]
  let lo = 0
  let hi = areas.length - 1
  while (lo < hi) {
    const mid = (lo + hi) >> 1
    if (areas[mid] < target) lo = mid + 1
    else hi = mid
  }
  const root = Math.sqrt(r1)
  const w0 = 1 - root
  const w1 = root * (1 - r2)
  const w2 = root * r2
  const a = vertexOf(s, lo, 0)
  const b = vertexOf(s, lo, 1)
  const c = vertexOf(s, lo, 2)
  const mix = (data: ArrayLike<number>, stride: number, axis: number) =>
    data[a * stride + axis] * w0 + data[b * stride + axis] * w1 + data[c * stride + axis] * w2
  out.x = mix(s.positions, 3, 0)
  out.y = mix(s.positions, 3, 1)
  out.z = mix(s.positions, 3, 2)
  out.nx = s.normals ? mix(s.normals, 3, 0) : 0
  out.ny = s.normals ? mix(s.normals, 3, 1) : 1
  out.nz = s.normals ? mix(s.normals, 3, 2) : 0
  out.u = s.uvs ? mix(s.uvs, 2, 0) : 0.5
  out.v = s.uvs ? mix(s.uvs, 2, 1) : 0.5
}

/**
 * Dentro ou fora, para malha fechada: um raio em +X conta quantas faces cruza
 * (ímpar = dentro). Os triângulos ficam numa grade em YZ, para o raio só testar
 * os da própria célula. Simplificado: malha aberta dá resultado sem sentido, e
 * por isso a caixa achatada (Plano, Grade) nem passa por aqui.
 */
function createInsideTest(s: ScatterSurface, box: Box) {
  const tris = triangleCount(s)
  const cells = Math.max(8, Math.min(128, Math.ceil(Math.sqrt(tris) / 2)))
  const buckets: number[][] = Array.from({ length: cells * cells }, () => [])
  const p = s.positions
  const [, y0, z0] = box.min
  const sy = cells / box.size[1]
  const sz = cells / box.size[2]
  const cell = (v: number) => Math.max(0, Math.min(cells - 1, Math.floor(v)))
  for (let t = 0; t < tris; t++) {
    let minY = Infinity
    let maxY = -Infinity
    let minZ = Infinity
    let maxZ = -Infinity
    for (let c = 0; c < 3; c++) {
      const i = vertexOf(s, t, c) * 3
      minY = Math.min(minY, p[i + 1])
      maxY = Math.max(maxY, p[i + 1])
      minZ = Math.min(minZ, p[i + 2])
      maxZ = Math.max(maxZ, p[i + 2])
    }
    for (let y = cell((minY - y0) * sy); y <= cell((maxY - y0) * sy); y++) {
      for (let z = cell((minZ - z0) * sz); z <= cell((maxZ - z0) * sz); z++) buckets[y * cells + z].push(t)
    }
  }
  return (x: number, y: number, z: number) => {
    let crossings = 0
    for (const t of buckets[cell((y - y0) * sy) * cells + cell((z - z0) * sz)]) {
      const a = vertexOf(s, t, 0) * 3
      const b = vertexOf(s, t, 1) * 3
      const c = vertexOf(s, t, 2) * 3
      // o ponto projetado em YZ cai no triângulo? baricêntricas 2D
      const d = (p[b + 2] - p[c + 2]) * (p[a + 1] - p[c + 1]) + (p[c + 1] - p[b + 1]) * (p[a + 2] - p[c + 2])
      if (d === 0) continue
      const w0 = ((p[b + 2] - p[c + 2]) * (y - p[c + 1]) + (p[c + 1] - p[b + 1]) * (z - p[c + 2])) / d
      const w1 = ((p[c + 2] - p[a + 2]) * (y - p[c + 1]) + (p[a + 1] - p[c + 1]) * (z - p[c + 2])) / d
      const w2 = 1 - w0 - w1
      if (w0 < 0 || w1 < 0 || w2 < 0) continue
      if (w0 * p[a] + w1 * p[b] + w2 * p[c] > x) crossings++
    }
    return crossings % 2 === 1
  }
}

/** escreve translação + rotação (quaternion) + escala uniforme na matriz da instância */
function writeMatrix(m: Float32Array, at: number, c: Candidate, qx: number, qy: number, qz: number, qw: number, s: number) {
  const xx = qx * (qx + qx)
  const xy = qx * (qy + qy)
  const xz = qx * (qz + qz)
  const yy = qy * (qy + qy)
  const yz = qy * (qz + qz)
  const zz = qz * (qz + qz)
  const wx = qw * (qx + qx)
  const wy = qw * (qy + qy)
  const wz = qw * (qz + qz)
  m[at] = (1 - (yy + zz)) * s
  m[at + 1] = (xy + wz) * s
  m[at + 2] = (xz - wy) * s
  m[at + 3] = 0
  m[at + 4] = (xy - wz) * s
  m[at + 5] = (1 - (xx + zz)) * s
  m[at + 6] = (yz + wx) * s
  m[at + 7] = 0
  m[at + 8] = (xz + wy) * s
  m[at + 9] = (yz - wx) * s
  m[at + 10] = (1 - (xx + yy)) * s
  m[at + 11] = 0
  m[at + 12] = c.x
  m[at + 13] = c.y
  m[at + 14] = c.z
  m[at + 15] = 1
}

/** (id, aleatório, escala) por instância, em sequência: o atributo \`instanceInfo\` */
export function instanceInfoArray(data: ScatterData): Float32Array {
  const out = new Float32Array(data.count * 3)
  for (let i = 0; i < data.count; i++) {
    out[i * 3] = data.ids[i]
    out[i * 3 + 1] = data.random[i]
    out[i * 3 + 2] = data.scales[i]
  }
  return out
}

/** \`count\` é o pedido: com rejeição, pode sair menos (o card mostra quantas saíram) */
export function scatter(surface: ScatterSurface | null, params: ScatterParams, density: ScatterDensity | null = null): ScatterData {
  const { mode, seed, minDistance, scaleMin, scaleMax, rotationRandom, alignToNormal } = params
  const count = Math.max(0, Math.floor(params.count))
  const rng = mulberry32(seed)
  const poisson = createPoisson(minDistance)
  const box = boundsOf(surface)
  const [axisA, axisB, axisC] = axesOf(box)

  const onSurface = mode === 'Superfície'
  const areas = onSurface && surface ? cumulativeArea(surface) : null
  const empty = onSurface && (!areas || areas.length === 0 || areas[areas.length - 1] <= 0)
  const inVolume = mode === 'Volume'
  const closed = inVolume && surface !== null && box.size.every((s) => s > 0)
  const inside = closed ? createInsideTest(surface!, box) : null
  const side = Math.ceil(Math.sqrt(count))
  const fixed = mode === 'Grade' || mode === 'Anel' // um candidato por lugar: rejeitar só abre buraco
  const rejects = inVolume || minDistance > 0 || density !== null
  const attempts = !fixed && rejects ? count * ATTEMPTS : count

  const matrices = new Float32Array(count * 16)
  const random = new Float32Array(count)
  const ids = new Float32Array(count)
  const scales = new Float32Array(count)
  const c: Candidate = { x: 0, y: 0, z: 0, nx: 0, ny: 1, nz: 0, u: 0.5, v: 0.5 }
  const point = [0, 0, 0]
  const normal = [0, 0, 0]
  const center = (axis: number) => box.min[axis] + box.size[axis] / 2
  const fit = (axis: number, t: number) => box.min[axis] + box.size[axis] * t
  const toUv = () => {
    c.u = box.size[axisA] > 0 ? (point[axisA] - box.min[axisA]) / box.size[axisA] : 0.5
    c.v = box.size[axisB] > 0 ? (point[axisB] - box.min[axisB]) / box.size[axisB] : 0.5
  }
  const commit = () => {
    c.x = point[0]
    c.y = point[1]
    c.z = point[2]
    c.nx = normal[0]
    c.ny = normal[1]
    c.nz = normal[2]
  }

  let n = 0
  for (let i = 0; i < attempts && n < count && !empty; i++) {
    const r0 = rng()
    const r1 = rng()
    const r2 = rng()
    const keep = rng()
    const size = rng()
    const r3 = rng()
    const r4 = rng()
    const r5 = rng()
    const value = rng()

    if (onSurface) sampleSurface(surface!, areas!, r0, r1, r2, c)
    else {
      normal[0] = 0
      normal[1] = 0
      normal[2] = 0
      if (inVolume) {
        point[0] = fit(0, r0)
        point[1] = fit(1, r1)
        point[2] = fit(2, r2)
        normal[1] = 1
      } else if (mode === 'Grade') {
        // células de tamanho igual, com o ponto no meio de cada uma
        point[axisA] = fit(axisA, ((i % side) + 0.5) / side)
        point[axisB] = fit(axisB, (Math.floor(i / side) + 0.5) / side)
        point[axisC] = center(axisC)
        normal[axisC] = 1
      } else {
        const angle = (i / count) * TWO_PI
        const radius = box.size[axisA] / 2
        point[axisA] = center(axisA) + Math.cos(angle) * radius
        point[axisB] = center(axisB) + Math.sin(angle) * radius
        point[axisC] = center(axisC)
        normal[axisA] = Math.cos(angle)
        normal[axisB] = Math.sin(angle)
      }
      toUv()
      commit()
    }

    if (inside && !inside(c.x, c.y, c.z)) continue
    if (density) {
      const col = Math.min(density.size - 1, Math.floor((c.u - Math.floor(c.u)) * density.size))
      const row = Math.min(density.size - 1, Math.floor((c.v - Math.floor(c.v)) * density.size))
      if (keep * 255 >= density.data[row * density.size + col]) continue
    }
    if (!poisson.accept(c.x, c.y, c.z)) continue

    let qx = 0
    let qy = 0
    let qz = 0
    let qw = 1
    if (alignToNormal) {
      // menor rotação que leva +Y até a normal
      const length = Math.sqrt(c.nx * c.nx + c.ny * c.ny + c.nz * c.nz) || 1
      const nx = c.nx / length
      const ny = c.ny / length
      const nz = c.nz / length
      if (ny < -0.999999) {
        qx = 1
        qw = 0
      } else {
        const w = Math.sqrt((1 + ny) * 2)
        qx = nz / w
        qz = -nx / w
        qw = w / 2
      }
      if (rotationRandom) {
        // giro em volta da própria normal: composição com (0, sin, 0, cos)
        const half = r3 * Math.PI
        const sy = Math.sin(half)
        const cy = Math.cos(half)
        const ax = qx
        const az = qz
        const aw = qw
        qx = ax * cy - az * sy
        qy = aw * sy
        qz = az * cy + ax * sy
        qw = aw * cy
      }
    } else if (rotationRandom) {
      // rotação uniforme
      const a = Math.sqrt(1 - r3)
      const b = Math.sqrt(r3)
      qx = a * Math.sin(TWO_PI * r4)
      qy = a * Math.cos(TWO_PI * r4)
      qz = b * Math.sin(TWO_PI * r5)
      qw = b * Math.cos(TWO_PI * r5)
    }

    const s = scaleMin + (scaleMax - scaleMin) * size
    writeMatrix(matrices, n * 16, c, qx, qy, qz, qw, s)
    random[n] = value
    ids[n] = i
    scales[n] = s
    n++
  }

  return n === count
    ? { matrices, random, ids, scales, count }
    : { matrices: matrices.slice(0, n * 16), random: random.slice(0, n), ids: ids.slice(0, n), scales: scales.slice(0, n), count: n }
}
